// HYPE CASH ad — one paused GSAP timeline. Every time comes from timing.json
// (window.TIMING, generated by scripts/render.mjs), so the picture follows the narration.
(() => {
  const T = window.TIMING;
  const E = T.emphasis;
  const W = (i) => T.words[i].start; // word start time by index
  const word = (text, from = 0) => T.words.findIndex((w, i) => i >= from && w.w.replace(/[.,:—]/g, "") === text);
  const q = (s) => document.querySelector(s);
  const qa = (s) => [...document.querySelectorAll(s)];
  const LEAD = 2 / 30; // text lands up to two frames before its word

  const tl = gsap.timeline({ paused: true, defaults: { ease: "power3.out" } });

  // ---------- initial states ----------
  gsap.set(["#s2", "#s3", "#s7"], { autoAlpha: 0 });
  gsap.set("#bgHome", { xPercent: -50, yPercent: -50, y: 300, scale: 1.28 });
  gsap.set("#bgSky", { xPercent: -50, yPercent: -50, scale: 1.15 });
  gsap.set("#bgHome2", { xPercent: -50, yPercent: -50, y: 430, scale: 1.2 });

  // ---------- S1 · Gancho (0 → 3.2) ----------
  const s1 = T.scenes[0];
  tl.fromTo("#bgHome", { scale: 1.28 }, { scale: 1.1, duration: s1.end, ease: "none" }, 0);
  tl.fromTo("#milhoes", { scale: 1.14, opacity: 1 }, { scale: 1, opacity: 1, duration: 0.42, ease: "expo.out" }, 0);
  tl.fromTo("#milhoes", { letterSpacing: "0.04em" }, { letterSpacing: "-0.03em", duration: 0.6, ease: "expo.out" }, 0);
  const s1words = qa("#s1line .word");
  [word("de"), word("pessoas"), word("vão"), word("falar"), word("de", 3)].forEach((wi, i) => {
    tl.fromTo(s1words[i], { opacity: 0, y: 40 }, { opacity: 1, y: 0, duration: 0.28 }, W(wi) - LEAD);
  });
  tl.to(["#milhoes", "#s1line"], { y: -120, duration: 0.5, ease: "power4.out" }, E.gta - LEAD);
  tl.fromTo("#gta", { scale: 1.7, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.38, ease: "expo.out" }, E.gta - LEAD);
  tl.fromTo("#flash", { opacity: 0.55 }, { opacity: 0, duration: 0.22, ease: "power2.out", immediateRender: false }, E.gta);
  // RGB split: big on impact, settles, small kick on "Seis"
  tl.fromTo("#gtaR", { x: -26, y: 6 }, { x: -5, y: 0, duration: 0.5, ease: "power2.out" }, E.gta);
  tl.fromTo("#gtaC", { x: 26, y: -6 }, { x: 5, y: 0, duration: 0.5, ease: "power2.out" }, E.gta);
  tl.to("#gtaR", { x: -16, duration: 0.06, yoyo: true, repeat: 1, ease: "none" }, W(word("Seis")));
  tl.to("#gtaC", { x: 16, duration: 0.06, yoyo: true, repeat: 1, ease: "none" }, W(word("Seis")));
  tl.to("#gta", { scale: 1.04, duration: s1.end - E.gta - 0.4, ease: "none" }, E.gta + 0.4);

  // wipe S1 → S2
  tl.fromTo("#wipe", { x: -1400 }, { x: 1900, duration: 0.42, ease: "power2.inOut" }, s1.end - 0.2);
  tl.set("#s1", { autoAlpha: 0 }, s1.end);
  tl.set("#s2", { autoAlpha: 1 }, s1.end);

  // ---------- S2 · Hype → conteúdo (3.2 → 7.05) ----------
  const s2 = T.scenes[1];
  tl.fromTo("#poucas", { clipPath: "inset(100% 0 0 0)", y: 60 }, { clipPath: "inset(0% 0 0 0)", y: 0, duration: 0.4 }, E.poucas - LEAD);
  tl.fromTo("#prontas", { opacity: 0, y: 30 }, { opacity: 1, y: 0, duration: 0.3 }, W(word("vão", 8)) - LEAD);
  tl.fromTo("#transf", { opacity: 0, y: 30 }, { opacity: 1, y: 0, duration: 0.3 }, W(word("pra")) - LEAD);
  tl.fromTo("#hype", { scale: 0.6, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.4, ease: "back.out(1.6)" }, E.hype - LEAD);
  tl.fromTo("#arrowPath", { strokeDasharray: 300, strokeDashoffset: 300 }, { strokeDashoffset: 0, duration: 0.35, ease: "power2.out" }, E.hype + 0.22);
  tl.fromTo("#conteudo", { scale: 1.25, opacity: 0, y: 30 }, { scale: 1, opacity: 1, y: 0, duration: 0.42, ease: "expo.out" }, E.conteudo - LEAD);
  tl.to("#hype", { opacity: 0.45, duration: 0.3 }, E.conteudo);
  [["#vc1", 1500, 1130, -8], ["#vc2", 1560, 1240, 3], ["#vc3", 1500, 1110, 9]].forEach(([s, y0, y1, r], i) => {
    tl.fromTo(s, { y: 0, rotation: 0, opacity: 0 }, { y: y1 - y0, rotation: r, opacity: 0.85, duration: 0.7, ease: "power3.out" }, E.conteudo - 0.1 + i * 0.07);
  });
  tl.to(["#poucas", "#prontas", "#transf"], { y: -30, duration: s2.end - E.conteudo, ease: "none" }, E.conteudo);
  tl.fromTo("#flash", { opacity: 0 }, { opacity: 0.85, duration: 0.08, ease: "none", immediateRender: false }, s2.end - 0.08);
  tl.set("#s2", { autoAlpha: 0 }, s2.end);
  tl.set("#s3", { autoAlpha: 1 }, s2.end);
  tl.to("#flash", { opacity: 0, duration: 0.25, ease: "power2.out" }, s2.end);

  // ---------- S3 · Revelação (7.05 → 8.85) ----------
  const s3 = T.scenes[2];
  gsap.set(["#pill", "#s5a", "#s5b", "#s6h", "#phone", ".badge", "#prog"], { autoAlpha: 0 });
  tl.fromTo("#skyDim", { opacity: 0.15 }, { opacity: 0.15, duration: 0.01 }, s3.start);
  tl.fromTo("#bgSky", { scale: 1.15 }, { scale: 1.32, duration: T.scenes[5].end - s3.start, ease: "none" }, s3.start);
  tl.fromTo("#conheca", { opacity: 0, y: 30 }, { opacity: 1, y: 0, duration: 0.35 }, E.conheca - LEAD);
  tl.fromTo("#logoWrap", { scale: 0.55, rotation: -6, opacity: 0 }, { scale: 1, rotation: 0, opacity: 1, duration: 0.5, ease: "back.out(1.5)" }, E.hypecash - LEAD);
  tl.fromTo("#sweep i", { left: "-30%" }, { left: "120%", duration: 0.6, ease: "power2.inOut" }, E.hypecash + 0.25);
  tl.to("#logoWrap", { scale: 1.05, duration: s3.end - E.hypecash - 0.5, ease: "none" }, E.hypecash + 0.5);

  // ---------- S4 · Playbook (8.85 → 13.95) ----------
  const s4 = T.scenes[3];
  tl.to("#conheca", { opacity: 0, y: -40, duration: 0.3, ease: "power2.in" }, s4.start - 0.05);
  tl.to("#logoWrap", { top: 250, scale: 0.42, duration: 0.55, ease: "power3.inOut" }, s4.start - 0.05);
  tl.to("#skyDim", { opacity: 0.62, duration: 0.6 }, s4.start);
  tl.fromTo("#phone", { autoAlpha: 1, y: 1300, rotationX: 18 }, { autoAlpha: 1, y: 0, rotationX: 0, duration: 0.75, ease: "power3.out", immediateRender: false }, s4.start);
  tl.fromTo("#pill", { autoAlpha: 0, scale: 0.8 }, { autoAlpha: 1, scale: 1, duration: 0.35, ease: "back.out(2)" }, E.playbook - LEAD);
  tl.fromTo("#scrMissoes", { scale: 1, transformOrigin: "50% 30%" }, { scale: 1.07, transformOrigin: "50% 30%", duration: E.central - s4.start, ease: "none" }, s4.start);
  tl.fromTo("#b6", { autoAlpha: 0, x: -260, rotation: -10 }, { autoAlpha: 1, x: 0, rotation: -3, duration: 0.45, ease: "back.out(1.6)" }, E.seis - LEAD);
  tl.fromTo("#bBonus", { autoAlpha: 0, x: 260, rotation: 10 }, { autoAlpha: 1, x: 0, rotation: 3, duration: 0.45, ease: "back.out(1.6)" }, E.bonus - LEAD);
  // screen change: Missões → Ferramentas (app-style slide)
  gsap.set(["#scrTools", "#scrM01", "#scrCheckWrap"], { xPercent: 100 });
  tl.to("#scrMissoes", { xPercent: -35, opacity: 0.4, duration: 0.45, ease: "power3.inOut" }, E.central - 0.12);
  tl.fromTo("#scrTools", { xPercent: 100 }, { xPercent: 0, duration: 0.45, ease: "power3.inOut" }, E.central - 0.12);
  tl.fromTo("#bTools", { autoAlpha: 0, x: -260, rotation: -8 }, { autoAlpha: 1, x: 0, rotation: -2, duration: 0.45, ease: "back.out(1.6)" }, E.central - LEAD);
  tl.fromTo("#scrTools", { y: 0 }, { y: -40, duration: s4.end - E.central, ease: "none" }, E.central + 0.3);

  // ---------- S5 · Da ideia à publicação (13.95 → 16.95) ----------
  const s5 = T.scenes[4];
  tl.to(".badge", { autoAlpha: 0, scale: 0.85, duration: 0.25, ease: "power2.in", stagger: 0.04 }, s5.start - 0.15);
  tl.to(["#pill", "#logoWrap"], { autoAlpha: 0, y: -80, duration: 0.3, ease: "power2.in" }, s5.start - 0.1);
  tl.to("#scrTools", { xPercent: -35, opacity: 0.4, duration: 0.45, ease: "power3.inOut" }, s5.start);
  tl.fromTo("#scrM01", { xPercent: 100 }, { xPercent: 0, duration: 0.45, ease: "power3.inOut" }, s5.start);
  tl.fromTo("#scrM01", { y: 0 }, { y: -30, duration: s5.end - s5.start, ease: "none" }, s5.start + 0.45);
  tl.fromTo("#s5a", { autoAlpha: 0, clipPath: "inset(0 100% 0 0)" }, { autoAlpha: 1, clipPath: "inset(0 0% 0 0)", duration: 0.4, ease: "power3.out" }, E.ideia - 0.15);
  tl.fromTo("#s5b", { autoAlpha: 0, y: 40, scale: 0.9 }, { autoAlpha: 1, y: 0, scale: 1, duration: 0.4, ease: "back.out(1.6)" }, E.publicar - LEAD);

  // ---------- S6 · Missão por missão (16.95 → 19.87) ----------
  const s6 = T.scenes[5];
  tl.to(["#s5a", "#s5b"], { autoAlpha: 0, y: -60, duration: 0.28, ease: "power2.in" }, s6.start - 0.1);
  tl.to("#scrM01", { xPercent: -35, opacity: 0.4, duration: 0.45, ease: "power3.inOut" }, s6.start);
  tl.fromTo("#scrCheckWrap", { xPercent: 100 }, { xPercent: 0, duration: 0.45, ease: "power3.inOut" }, s6.start);
  const s6words = qa("#s6h .word");
  [E.missao, W(word("por", 40)), W(word("missão", 47))].forEach((t, i) => {
    tl.fromTo(s6words[i], { opacity: 0, y: 50 }, { opacity: 1, y: 0, duration: 0.3 }, t - LEAD);
  });
  tl.set("#s6h", { autoAlpha: 1 }, E.missao - LEAD);
  // checkboxes of the real checklist: centres measured on the screenshot (920px-wide preview)
  const k = 580 / 920, cropTop = 330;
  [1168, 1297, 1425, 1553].forEach((y, i) => gsap.set(`#c${i + 1}`, { left: 87 * k, top: (y - cropTop) * k, scale: 0 }));
  gsap.set("#chkCount", { top: (1078 - cropTop) * k - 15 });
  const checkTimes = [0, 1, 2, 3].map((i) => E.checklist + i * 0.2);
  checkTimes.forEach((t, i) => {
    tl.fromTo(`#c${i + 1}`, { scale: 0 }, { scale: 1, duration: 0.22, ease: "back.out(2.5)" }, t);
    tl.fromTo(`#c${i + 1} path`, { strokeDashoffset: 1 }, { strokeDashoffset: 0, duration: 0.2, ease: "power2.out" }, t + 0.08);
  });
  tl.fromTo("#scrCheckWrap", { y: 0 }, { y: -60, duration: s6.end - s6.start - 0.5, ease: "none" }, s6.start + 0.5);
  tl.fromTo("#prog", { autoAlpha: 0, y: 80 }, { autoAlpha: 1, y: 0, duration: 0.4 }, E.checklist + 0.2);
  tl.fromTo("#fill", { scaleX: 0 }, { scaleX: 1, duration: 0.8, ease: "power2.inOut" }, E.progresso - LEAD);

  // ---------- S7 · CTA (19.87 → end) ----------
  const s7 = T.scenes[6];
  tl.fromTo("#flash", { opacity: 0 }, { opacity: 0.9, duration: 0.08, ease: "none", immediateRender: false }, s7.start - 0.08);
  tl.set("#s3", { autoAlpha: 0 }, s7.start);
  tl.set("#s7", { autoAlpha: 1 }, s7.start);
  tl.to("#flash", { opacity: 0, duration: 0.3, ease: "power2.out" }, s7.start);
  tl.fromTo("#bgHome2", { scale: 1.2 }, { scale: 1.06, duration: T.video_duration_s - s7.start, ease: "none" }, s7.start);
  const ew = qa("#entre .word");
  [E.entre, W(word("no", 50)), W(word("jogo"))].forEach((t, i) => {
    tl.fromTo(ew[i], { opacity: 0, y: 70, scale: 1.15 }, { opacity: 1, y: 0, scale: 1, duration: 0.32, ease: "expo.out" }, t - LEAD);
  });
  gsap.set("#entre", { y: 260, scale: 1.25 });
  tl.to("#entre", { y: 0, scale: 1, duration: 0.55, ease: "power3.inOut" }, W(word("Toque")) - 0.05);
  tl.fromTo("#endLogo", { autoAlpha: 0, y: -120, scale: 0.8 }, { autoAlpha: 1, y: 0, scale: 1, duration: 0.5, ease: "back.out(1.4)" }, W(word("Toque")));
  tl.fromTo("#cta", { autoAlpha: 0, scale: 0.7 }, { autoAlpha: 1, scale: 1, duration: 0.45, ease: "back.out(1.8)" }, E.botao - 0.2);
  tl.to("#cta", { scale: 1.06, duration: 0.16, yoyo: true, repeat: 1, ease: "power1.inOut" }, E.botao + 0.3);
  tl.fromTo("#cta .shine", { left: -200 }, { left: 1000, duration: 0.7, ease: "power2.inOut" }, E.botao + 0.3);
  tl.fromTo("#url", { autoAlpha: 0, y: 20 }, { autoAlpha: 1, y: 0, duration: 0.35 }, E.botao + 0.35);
  tl.to("#cta", { scale: 1.06, duration: 0.16, yoyo: true, repeat: 1, ease: "power1.inOut" }, E.hypecash_end);
  tl.fromTo("#cta .shine", { left: -200 }, { left: 1000, duration: 0.7, ease: "power2.inOut", immediateRender: false }, E.hypecash_end);
  tl.fromTo("#chev", { autoAlpha: 0 }, { autoAlpha: 1, duration: 0.3 }, E.botao);
  tl.fromTo("#chev", { y: 0 }, { y: 26, duration: 0.42, yoyo: true, repeat: 6, ease: "sine.inOut" }, E.botao);
  tl.fromTo("#legal", { autoAlpha: 0 }, { autoAlpha: 1, duration: 0.4 }, E.botao + 0.6);
  tl.set({}, {}, T.video_duration_s); // timeline length = video length

  // ---------- deterministic seek ----------
  const turb = q("#turb");
  window.seek = (t) => {
    tl.seek(t, false);
    // text readouts are derived from the timeline state, never from onUpdate side effects
    q("#chkCount").textContent = `Checklist (${checkTimes.filter((c) => t >= c + 0.1).length}/4)`;
    q("#pct").textContent = `${Math.round(gsap.getProperty("#fill", "scaleX") * 100)}%`;
    turb.setAttribute("seed", String(1 + (Math.round(t * T.fps) % 12))); // grain changes per frame, seeded
  };
  window.duration = tl.duration();
  const faces = ["700 10px Poppins", "800 10px Poppins", "900 10px Poppins", "400 10px Inter", "500 10px Inter", "600 10px Inter", "700 10px Inter"];
  window.__ready = Promise.all([
    ...faces.map((f) => document.fonts.load(f)),
    document.fonts.ready,
    ...[...document.images].map((img) => (img.complete ? img.decode().catch(() => {}) : new Promise((r) => (img.onload = img.onerror = r)))),
  ]).then(() => {
    const fonts = Object.fromEntries([...document.fonts].map((f) => [`${f.family} ${f.weight}`, f.status]));
    window.seek(0);
    return { fonts, images: document.images.length, duration: tl.duration() };
  });
})();
